def list_page(items, cursor, size):
    """Cursor-based pagination with ties.

    Order: score descending, then id ascending (ids are unique strings).
    cursor None means the first page; next_cursor is None after the last page.
    Walking all pages must return every item exactly once even when many items share a score.
    The cursor is an opaque string that must not contain titles or other item data besides score and id.
    size < 1 or a malformed cursor raises ValueError.
    Do not modify items.
    """
    if not isinstance(size, int) or size < 1:
        raise ValueError("size must be a positive integer")

    # Sort all items by (-score, id) to get deterministic ordering
    ordered = sorted(items, key=lambda x: (-x['score'], x['id']))

    if cursor is None:
        # First page: return the first `size` items
        start_idx = 0
    else:
        # Decode the cursor
        try:
            prev_score, prev_id = _decode_cursor(cursor)
        except Exception:
            raise ValueError("malformed cursor")

        # Find the starting position: we want items that come AFTER (prev_score, prev_id)
        # in the sort order. Since ids are unique, there's exactly one item with (prev_score, prev_id).
        start_idx = None
        for i, item in enumerate(ordered):
            if item['score'] == prev_score and item['id'] == prev_id:
                start_idx = i + 1
                break

        if start_idx is None or start_idx >= len(ordered):
            return [], None

    page = ordered[start_idx:start_idx + size]

    # next_cursor is None only when there are no more items after this page
    if start_idx + size >= len(ordered) or not page:
        next_cursor = None
    else:
        next_cursor = _encode_cursor(page[-1]['score'], page[-1]['id'])

    return page, next_cursor
